-- Employee master from HR's Keka export "All Employees Master Data" (20 Nov 2026, 92 people) and the "Employee Levels" sheet.
-- Adds gender, marital status, shift, weekly off, employee level (L0 directors … L3) and team, and fills company, store,
-- department, designation, joining date, employment type, reporting manager and missing Biometric IDs from Keka.
-- Keka's value wins when it has one; empty cells leave what HR entered here. Name, date of birth, contact and email are
-- only used for people not yet on the list (DBYA0010, DBYA0094). PAN, Aadhaar, PF and UAN are not read.
-- Store: Keka's Location, or the Levels sheet's store when Keka says "Head Office".
-- Levels people with no Employee ID in Keka (the four directors and 23 staff) are not added.

ALTER TABLE employees ADD COLUMN IF NOT EXISTS gender text CHECK (gender IN ('Male', 'Female', 'Other'));
ALTER TABLE employees ADD COLUMN IF NOT EXISTS marital_status text CHECK (marital_status IN ('Single', 'Married', 'Divorced', 'Widowed'));
ALTER TABLE employees ADD COLUMN IF NOT EXISTS employee_level text CHECK (employee_level IN ('L0', 'L1', 'L2', 'L3'));
ALTER TABLE employees ADD COLUMN IF NOT EXISTS team text;
ALTER TABLE employees ADD COLUMN IF NOT EXISTS shift text;
ALTER TABLE employees ADD COLUMN IF NOT EXISTS weekly_off text;
--> statement-breakpoint
CREATE TEMP TABLE keka (code text, full_name text, email text, dob date, phone text, bio text, company text, store text, department text, designation text, joined date, emp_type text, manager text, gender text, marital text, shift text, weekly_off text, level text, team text);
--> statement-breakpoint
SELECT k.code, k.full_name, k.email, k.dob, k.phone FROM keka k
WHERE k.full_name IS NOT NULL AND NOT EXISTS (SELECT 1 FROM employees e WHERE e.employee_code = k.code);
--> statement-breakpoint
UPDATE employees e SET
  company = COALESCE(k.company, e.company), store_code = COALESCE(k.store, e.store_code), department = COALESCE(k.department, e.department),
  designation = COALESCE(k.designation, e.designation), joining_date = COALESCE(k.joined, e.joining_date), employment_type = COALESCE(k.emp_type, e.employment_type),
  reporting_manager = COALESCE((SELECT m.employee_code FROM employees m WHERE m.employee_code = k.manager AND m.employee_code <> e.employee_code), e.reporting_manager),
  gender = COALESCE(k.gender, e.gender), marital_status = COALESCE(k.marital, e.marital_status), shift = COALESCE(k.shift, e.shift),
  weekly_off = COALESCE(k.weekly_off, e.weekly_off), employee_level = COALESCE(k.level, e.employee_level), team = COALESCE(k.team, e.team),
  updated_at = now()
FROM keka k WHERE k.code = e.employee_code;
--> statement-breakpoint
-- A Biometric ID only goes where the employee has none and nobody else holds it.
UPDATE employees e SET biometric_id = k.bio, updated_at = now()
FROM keka k
WHERE k.code = e.employee_code AND e.biometric_id IS NULL AND k.bio IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM employees o WHERE o.biometric_id = k.bio)
  AND (SELECT count(*) FROM keka d WHERE d.bio = k.bio) = 1;
--> statement-breakpoint
DROP TABLE keka;
